\label{Triangulated_vector_conf}
    A \emph{triangulated vector configuration} in \({\mathbb{R}}^d\) is a pair \((V, \mathcal{T})\) where
    \begin{itemize}
        \item \(V = (v_1, \dots, v_n)\) is a list of vectors in \({\mathbb{R}}^d\), admitting repetitions. We assume that \({\mathbb{R}}^d = \operatorname{Span}_{\mathbb{R}} (v_1, \dots, v_n)\).
        \item We call \(\tau \subseteq \{1,\dots,n\}\) a \emph{simplex} if \(\{v_j:j\in\tau\}\) is a set of linearly independent vectors. A simplicial \emph{cone} over \(\tau \in \mathcal{T}\) is the convex set \(\operatorname{cone}(\tau) = \{\sum_{j\in\tau}{\mathbb{R}}_{\geq 0}v_j\}\). The triangulation \(\mathcal{T}\) is an abstract simplicial complex of these simplexes, that is:
        \begin{itemize}
            \item \(\operatorname{cone}(\tau) \cap \operatorname{cone}(\tau') = \operatorname{cone}(\tau\cap\tau')\) for all \(\tau,\tau' \in \mathcal{T}\),
            \item \(\bigcup_{\tau \in \mathcal{T}} \operatorname{cone}(\tau) \supseteq \operatorname{cone}(V)\).
        \end{itemize}
        In particular \(\operatorname{cone}(\emptyset) = \{0\}\), while, by convention, \(\operatorname{cone}(V) = \sum_{j=1}^n {\mathbb{R}}_{\geq} v_j\).
    \end{itemize}

\label{rat_core_and_rat_envelope}
    Let \(W\) be a subspace of \({\mathbb{R}}^n\). We say that \(W\) is \emph{rational} if \((W \cap {\mathbb{Q}}^n) \otimes {\mathbb{R}} = W\). We call the \emph{rational core} of \(W\) the rational subspace
    \begin{equation*}
        \operatorname{core}_{{\mathbb{Q}}}(W) = (W \cap {\mathbb{Q}}) \otimes {\mathbb{R}} = \bigcup_{\substack{T \subseteq W \\ T \text{ rational}}} T.
    \end{equation*}
    On the other hand, we define the \emph{rational envelope} of \(W\) as
    \begin{equation*}
        W^{\mathbb{Q}} = \bigcap_{\substack{T \supseteq W \\ T \text{ rational}}} T.
    \end{equation*}

    We denote the dimension of these spaces as \(a(W) = \dim \operatorname{core}_{{\mathbb{Q}}}(W)\) and \(b(W) = \dim W^{{\mathbb{Q}}}\); clearly \(0 \leq a(W) \leq \dim W \leq b(W) \leq n\).

\label{rational_relation_def}
    Analogous quantities can be associated to any vector configuration \(V\). For these we set the space of linear relations
    \begin{equation*}
        \operatorname{Rel}(V) = \left\{c \in {\mathbb{R}}^n : \sum_{j=1}^n c_j v_j = 0\right\} \subseteq {\mathbb{R}}^n;
    \end{equation*}
    and we define \(a(V) \coloneqq a(\operatorname{Rel}(V))\) and \(b(V) \coloneqq b(\operatorname{Rel}(V))\).

\label{properties_of_vector_conf}
    We say that a vector configuration \(V = (v_1,\dots,v_n)\) in \({\mathbb{R}}^d\) is
        \begin{itemize}
            \item \emph{odd} if \(n - d = 2m + 1\) for some \(m > 0\),
            \item \emph{graded} if there exists an affine hyperplane \(H \subset E\) such that \(v_j \in H\) for any \(v_j \in V\),
            \item \emph{balanced} if \(\sum_i v_i = 0\).
        \end{itemize}

Let \(\mathrm{Cf}_{\mathbb{R}}(n,d)\) be the set of vector configurations in \({\mathbb{R}}^d\) of cardinality \(n\). Let \(V \in \mathrm{Cf}_{\mathbb{R}}(n,d)\) and \(W \in \mathrm{Cf}_{\mathbb{R}}(n,n-d)\) be two vector configurations in \({\mathbb{R}}^d\) and \({\mathbb{R}}^{n-d}\) respectively. We say that \(V\) and \(W\) are in \emph{Gale duality}, or equivalently, that one is a \emph{Gale Transform} of the other, if
    \begin{equation}
        \label{Gale_duality_definition}
        \operatorname{Rel}(V) \overset{\perp}{\oplus} \operatorname{Rel}(W) = {\mathbb{R}}^n.
    \end{equation}

Since the rationality indices \(a(-)\) and \(b(-)\) in \zcref[S]{rat_core_and_rat_envelope} are well-defined on the classes in \(\mathrm{Cf}_{\mathbb{R}}(n,d)/_\sim\), we easily obtain from \zcref[S]{Gale_duality_definition} that, for any \(V \in \mathrm{Cf}_{\mathbb{R}}(n,d)\),
    \begin{equation}
        \label{rat_degree_Gale_Dual}
        a([V]_{\mathbb{R}}) = n - b(\mathfrak{G}([V]_{\mathbb{R}})) \quad \text{and} \quad b([V]_{\mathbb{R}}) = n - a(\mathfrak{G}([V]_{\mathbb{R}})).
    \end{equation}

Let \(V \in [V]_{\mathbb{R}}\) be a representative of the class. Denoting by \(\{e_j\}_{j=1}^n\) the canonical basis of \({\mathbb{R}}^n\), we observe that \([V]_{\mathbb{R}}\) is balanced if and only if \(\mathbbm{1}_n \coloneqq \sum_{j=1}^n e_j \in \operatorname{Rel}(V)\), by definition of Gale duality, this is equivalent to \(\operatorname{Rel}(W) \subseteq \mathbbm{1}_n^\perp\) for any \(W \in \mathfrak{G}([V]_{\mathbb{R}})\). Let this be \(W = (w_1,\dots, w_n)\). Consider the linear functional \(\varphi = \sum_{j=1}^n e_j^*\) and the linear map
    \begin{align*}
        \pi : {\mathbb{R}}^n &\longrightarrow \operatorname{Span}(w_1,\dots,w_n)\\
        e_j &\longmapsto w_j
    \end{align*}
    Since \(\ker\varphi = \mathbbm{1}_n^\perp\) and \(\operatorname{Rel}(W) = \ker\pi\), the inclusion \(\operatorname{Rel}(W) \subseteq \mathbbm{1}_n^\perp\) is equivalent to \(\varphi \circ \ker\pi = 0\). As \(\pi = \operatorname{coker}(\ker\pi)\), this holds if and only if there exists a linear functional \(\psi :{\mathbb{R}}^{n-d} \to {\mathbb{R}}\) closing the diagram
    \begin{equation*}
        \begin{tikzcd}
            \empty \ar[r,"\ker\pi"] & {\mathbb{R}}^n \ar[r,"\pi"] \ar[d,"\varphi"'] & \operatorname{Span}(w_1,\dots,w_n) \ar[dl,dashed,"\exists ! \psi"]\\
            & {\mathbb{R}}
        \end{tikzcd}
    \end{equation*}
    Therefore we have \(\psi(w_j) = \varphi(e_j) = 1\) for any \(j\), and \(\psi(w_j - w_n) = 0\) for any \(j\). Thus, we have constructed an affine hyperplane \(w_n + \ker\psi\) containing all the vectors in \(W\), hence proving it is graded. Conversely, supposing that \(W\) is graded, we observe that such a hyperplane determines a map \(\psi\) fitting in the diagram above, thus, reversing all the implications in the proof, we conclude that \(V\) is balanced.

Let \(\Lambda^{\mathbb{R}}\) be a configuration of \(n\) points in \(\mathbb{A}^{2m}_{\mathbb{R}}\). We define the space of their \emph{affine relations} as
    \begin{equation*}
        \operatorname{Rel}_\text{aff}(\Lambda^{\mathbb{R}}) = \left\{c \in {\mathbb{R}}^{n} : \sum_{j=1}^n c_j \Lambda^{\mathbb{R}}_j = 0, \sum_{j=1}^n c_j = 0 \right\}.
    \end{equation*}

Let \(n\) be the number of vectors in the original configuration \((V,\mathcal{T})\); consequently, \(n+k\) is the number of vectors in the augmented configuration \((V',\mathcal{T}')\), the first \(k\) of which are ghosts. Thus, for any \(\tau' \in \mathcal{T}'\), \(j \in \tau'\) if and only if \(j-k \in \tau\). We can write this shift compactly as \(\tau' = \tau + k\). With this notation, applying Gale Transform, we have
    \begin{equation*}
        \mathcal{T}'^* = \big\{\{1,\dots,k\} \cup (\tau^* + k) : \tau^* \in \mathcal{T}^*\big\}.
    \end{equation*}
    Therefore, any \(\tau'^* \in \mathcal{T}'^*\) can be written as \(\tau'^* = \{1,\dots,k\} \cup (\tau^* + k)\) for a unique \(\tau^* \in \mathcal{T}^*\). So
    \begin{equation*}
        \bigcap_{j \in \tau'^*} D(z_j) = \bigcap_{j\in \{1,\dots,k\}} D(z_j) \cap \bigcap_{j \in \tau^* + k} D(z_j) = (({\mathbb{C}}^*)^k \times {\mathbb{C}}^{n}) \cap \bigcap_{j \in \tau^* + k} D(z_j) = ({\mathbb{C}}^*)^k \times \bigcap_{j \in \tau^*+k} D(z_j).
    \end{equation*}
    Taking the union over \(\tau'^* \in \mathcal{T}^*\), we obtain
    \begin{equation*}
        U(\mathcal{T}') = \bigcup_{\tau'^* \in \mathcal{T}'^*} \bigcap_{j \in \tau'^*} D(z_j) = ({\mathbb{C}}^*)^k \times \bigcup_{\tau^* \in \mathcal{T}^*} \bigcap_{j \in \tau^*+k} D(z_j) = ({\mathbb{C}}^*)^k \times U(\mathcal{T}). \qedhere
    \end{equation*}

From the definition of \(U(\mathcal{T})\), its complementary \(S\) can be written as
    \begin{equation*}
        S = \bigcap_{\tau^* \in \mathcal{T}^*} \bigcup_{j \in \tau^*} V(z_j),
    \end{equation*}
    with \(V(z_j)\) Zariski closed subsets in \({\mathbb{C}}^n\); notice that \(S \neq \emptyset\) as \(0 \in V(z_j)\) for any \(j \in \{1,\dots,n\}\). The proof consists in showing that \(S\) coincides with
    \begin{equation*}
        A = \bigcup_{\tau \notin \mathcal{T}} \bigcap_{j \in \tau} V(z_j).
    \end{equation*}
    Let \(\underline{z} \in A\), thus there exists \(\sigma \notin \mathcal{T}\) such that \(z_j = 0\) for all \(j \in \sigma\). We observe that, for any \(\tau^* \in \mathcal{T}^*\), by construction \(\sigma \not\supseteq \tau\); thus it must intersect its complementary \(\tau^*\) in some index \(j \in \sigma \cap \tau^*\). Hence, for any \(\tau^* \in \mathcal{T}^*\), one has \(\prod_{j \in \tau^*} z_j = 0\), thus \(\underline{z} \in S\).

    Conversely, let \(\underline{z} \in S\); therefore, for any \(\tau^* \in \mathcal{T}^*\) there exists \(j \in \tau^*\) such that \(z_j = 0\). Consider the set
    \begin{equation*}
        J = \bigcup_{\tau^* \in \mathcal{T}^*} \{j \in \tau^* : z_j = 0\} \eqqcolon \bigcup_{\tau^* \in \mathcal{T}^*} J_{\tau^*},
    \end{equation*}
    and the intersections \(J_{\tau^*} \cap \tau^*\): these are assured to be nonempty by the existence of \(z \in S\). Notice that \(J \cap \tau^* \neq \emptyset\) if and only if \(J \notin \mathcal{T}\); since the former condition is always satisfied and by construction \(z_j = 0\) for all \(j \in J\), we conclude that \(\underline{z} \in A\). In particular, \(S = A\) implies that \(U(\mathcal{T})\) can be written in the form
    \begin{equation*}
        U(\mathcal{T}) = {\mathbb{C}}^n \setminus \bigcup_\ell S_\ell,
    \end{equation*}
    for some coordinate subspaces \(S_\ell\). Notice that, since \(\emptyset \in \mathcal{T}\), none of these can be the whole \({\mathbb{C}}^n\).

    Finally, we observe that if there are no indispensable indices in \(\mathcal{T}^*\), then \(\{j\} \in \mathcal{T}\) for any \(j \in \{1,\dots,n\}\). Hence for any \(\tau \notin \mathcal{T}\)
    \begin{equation*}
        \operatorname{codim}_{{\mathbb{C}}^n} \bigcap_{j \in \tau} V(z_j) = \sum_{j \in \tau} \operatorname{codim}_{{\mathbb{C}}^n} V(z_j) = \#\tau > 1,
    \end{equation*}
    and so \(c = \min_\ell \operatorname{codim}_{{\mathbb{C}}^n} S_\ell > 1\). On the other hand, for any indispensable index \(i \in \mathcal{T}^*\) we have \(V(z_i) \subseteq S\), since this is a coordinate hyperplane, we conclude that \(c = 1\).

By construction \(\Lambda = \Lambda^{\mathbb{R}} \leftindex^{t}{\Pi}\) for some period matrix \(\Pi\). Thus, any affine rational relation in \(\operatorname{Rel}(\Lambda^{\mathbb{R}}) \cap {\mathbb{Q}}^n\) induces an affine rational relation among the \(\Lambda_j\)'s; this correspondence is clearly injective. Conversely, any \(c \in \operatorname{Rel}_\text{aff}(\Lambda) \cap {\mathbb{Q}}^{n}\) satisfies \(c \,\Lambda^{\mathbb{R}} \leftindex^{t}{\Pi} = 0\); taking complex conjugates, we obtain
    \begin{equation*}
        0 = \overline{c \,\Lambda^{\mathbb{R}} \leftindex^{t}{\Pi}} = c \,\Lambda^{\mathbb{R}} \leftindex^{t}{\overline{\Pi}},
    \end{equation*}
    hence,
    \begin{equation*}
        c \,\Lambda^{\mathbb{R}}\, [\leftindex^{t}{\Pi} | \leftindex^{t}{\overline{\Pi}}] = 0.
    \end{equation*}
    Being \(\Pi\) a period matrix, \([\leftindex^{t}{\Pi} | \leftindex^{t}{\overline{\Pi}}] \in \mathrm{GL}(2m,{\mathbb{C}})\), whence \(c \, \Lambda^{\mathbb{R}} = 0\).

Let \((\Lambda,\mathcal{T}^*)\) be an LVMB datum. We define the \emph{group of first integrals} of the configuration as the \({\mathbb{Z}}\)-module
    \begin{equation*}
        I(\Lambda) = \operatorname{core}_{{\mathbb{Q}}}(\operatorname{Rel}_\text{aff}(\Lambda)) \cap {\mathbb{Z}}^n;
    \end{equation*}
    and we refer to its elements simply as \emph{first integrals}.

Let \(C\) be a non-empty closed convex subset in \({\mathbb{R}}^n\); fix \(x \in C\). The \emph{asymptotic cone} of \(C\) is defined as the convex set
    \begin{equation*}
        C_\infty = \{ v \in {\mathbb{R}}^n : x + tv \in C \text{ for all } t >0\}.
    \end{equation*}
    As \(C\) is convex, this definition does not depend on the choice of \(x \in C\).

Both \(J+\operatorname{Rel}(\Lambda)\) and \({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0}\) are closed convex subsets of \({\mathbb{R}}^{n-1}\); moreover, by assumption, they intersect at \(J\). Thus, taking the asymptotic cones, we have
    \begin{equation}
        \label{equation1}
        (J+\operatorname{Rel}(\Lambda))_\infty \cap ({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0})_\infty = \operatorname{Rel}(\Lambda) \cap ({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0})
    \end{equation}
    as \(J+\operatorname{Rel}(\Lambda)\) is an affine subspace and \({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0}\) a closed convex cone. 

    By the geometry of the LVMB datum \(\Lambda\), the right-hand side of \zcref{equation1} is \(\{0\}\).  Indeed, by Gale duality, \(\operatorname{Rel}(\Lambda)\) is spanned by the rows of the matrix
    \begin{equation*}
        \begin{bmatrix}
            \rule[-1ex]{0.5pt}{2.5ex} && \rule[-1ex]{0.5pt}{2.5ex}\\
            v_1 & \cdots & v_{n-1}\\
            \rule[-1ex]{0.5pt}{2.5ex} && \rule[-1ex]{0.5pt}{2.5ex}
        \end{bmatrix},
    \end{equation*}
    with \(\left(-\sum_{j=1}^{n-1} v_j, v_1,\dots, v_{n-1}\right)\) forming an odd and balanced vector configuration that is Gale dual to \(\Lambda^{\mathbb{R}}\). Thus, any \(w \in \operatorname{Rel}(\Lambda)\) is of the form \(w = \sum_{\ell=1}^{n-1} \langle v_\ell,v\rangle e_\ell\) for some \(v \in {\mathbb{R}}^d\). If \(\langle v_j, v\rangle\) were all non-negative (or all non-positive) for \(j=k,\dots,n-1\), the vectors \(v_k,\dots, v_{n-1}\) would lie in a closed half plane of \({\mathbb{R}}^d\). This never happens, since the non-ghost vectors of a triangulated vector configuration span the rays of a complete fan.

    The statement then follows observing that, by \zcref[S]{intersection_compatibility},
    \begin{equation*}
         ((J+\operatorname{Rel}(\Lambda)) \cap ( {\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0}))_\infty = (J+\operatorname{Rel}(\Lambda))_\infty \cap ({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0})_\infty = \{0\},
    \end{equation*}
    whence \((J+\operatorname{Rel}(\Lambda)) \cap ( {\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0})\) is compact.

\label{dim_W}
    Let \((\Lambda,\mathcal{T})\) be an LVMB configuration with \(k \geq 1\) indispensable points; let these be \(0,\Lambda_2,\dots,\Lambda_{k}\). Consider the complex vector space \(W = \operatorname{Span}_{{\mathbb{C}}} (L^1,\dots,L^m) \subseteq {\mathbb{C}}^{k-1}\) spanned by the columns of the matrix
    \begin{equation*}
        \begin{bmatrix}
            \rule[-1ex]{0.5pt}{2.5ex} &&\rule[-1ex]{0.5pt}{2.5ex}\\
            L^1 &\cdots & L^m\\
            \rule[-1ex]{0.5pt}{2.5ex} && \rule[-1ex]{0.5pt}{2.5ex}
        \end{bmatrix} =
        \begin{bmatrix}
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} \Lambda_2 \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}\\
            \vdots\\
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} \Lambda_{k} \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} 
        \end{bmatrix}.
    \end{equation*}
     Then 
    \begin{equation*}
        \left\lceil \frac{k-1}{2} \right\rceil \leq \dim_{{\mathbb{C}}} W \leq \min(k-1,m),
    \end{equation*}
    and 
    \begin{equation*}
        \dim_{{\mathbb{R}}} (W \cap {\mathbb{R}}^{k-1}) = 2 \dim_{{\mathbb{C}}} W - (k-1).
    \end{equation*}

By \cite[Prop.~1.5]{Thiella2026preprint}, the datum \(\Lambda\) of any LVMB pair \((\Lambda,\mathcal{T}^*)\) can be written as
    \begin{equation}
        \label{good_period_relation}
        \Lambda = \Lambda^{{\mathbb{R}}}_\text{good} \Pi^t,
    \end{equation}
    with \(\Lambda^{{\mathbb{R}}}_\text{good}\) a Gale dual configuration of some odd and balanced vector configuration of the form
    \begin{equation*}
        \Lambda^{{\mathbb{R}}}_\text{good} =
        \begin{bmatrix}
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} (\Lambda^{{\mathbb{R}}}_\text{good})_1 \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}\\
            \vdots\\
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} (\Lambda^{{\mathbb{R}}}_\text{good})_k  \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}
        \end{bmatrix}
        =
        \begin{bNiceArray}{c|c}[margin]
            \Block{1-2}{0} &\\
            \hline
            I_{k-1} & 0 \\
            \hline
            \Block{1-2}{[\ell_{ij}]}         
        \end{bNiceArray},
    \end{equation*}
    with \(\ell_{ij} \in {\mathbb{R}}\), and \(\Pi \in {\mathbb{C}}^{m \times 2m}\) a suitable period matrix. Because of \zcref{good_period_relation}, such a \(\Pi\) is of the form
    \begin{equation*}
        \Pi =
        \begin{bNiceArray}{c|ccc|c}
            \rule[-1ex]{0.5pt}{2.5ex} & \rule[-1ex]{0.5pt}{2.5ex} & &\rule[-1ex]{0.5pt}{2.5ex} &\Block{3-1}{*} \\
            \Pi^1 & \Lambda_2 & \Cdots & \Lambda_k\\
            \rule[-1ex]{0.5pt}{2.5ex} & \rule[-1ex]{0.5pt}{2.5ex} & &\rule[-1ex]{0.5pt}{2.5ex}
        \end{bNiceArray}
        \eqqcolon
        \begin{bNiceArray}{c|c|c}
            \rule[-1ex]{0.5pt}{2.5ex} & \Block{3-1}{P} & \Block{3-1}{*}\\
            \Pi^1 \\
            \rule[-1ex]{0.5pt}{2.5ex}
        \end{bNiceArray}
    \end{equation*} 
    for some \(P \in {\mathbb{C}}^{m \times (k-1)}\). Since the columns of \(\Pi\) are \({\mathbb{R}}\)-linearly independent, the column rank satisfies \(\operatorname{rk}_{\mathbb{R}}^\text{col} P = k-1\); this also fulfils \(\operatorname{rk}_{\mathbb{R}}^\text{col} P \leq 2 \operatorname{rk}_{\mathbb{C}}^\text{col} P\) as \(\operatorname{Span}_{{\mathbb{R}}}(P^1,\dots,P^{k-1}) \subseteq \operatorname{Span}_{{\mathbb{C}}}(P^1,\dots,P^{k-1})_{\mathbb{R}}\). Therefore,
    \begin{equation*}
        \operatorname{rk}_{{\mathbb{C}}}^\text{col} P \geq \left\lceil \frac{k-1}{2} \right\rceil.
    \end{equation*}
    On the other hand, we immediately have \(\operatorname{rk}_{{\mathbb{C}}}^\text{col} P \leq \min(k-1,m)\). Since \(W\) is spanned by the \emph{rows} of \(P\), the first part of the statement then follows by observing that \(\dim_{\mathbb{C}} W = \operatorname{rk}_{{\mathbb{C}}}^\text{row} P = \operatorname{rk}_{{\mathbb{C}}}^\text{col} P\).

    For the second part, we consider the vector subspace
    \begin{equation*}
        S = \{s \in {\mathbb{C}}^{k-1} : P s = 0\}.
    \end{equation*}
    Since \(P\) has complex rank \(r \coloneqq \dim_{{\mathbb{C}}}W\), we have \(\dim_{{\mathbb{C}}} S = k-1-r\); moreover, as \(W\) is spanned by the \emph{rows} of \(P\), one has \(W = \overline{S}^\perp\) with respect to the standard Hermitian product of \({\mathbb{C}}^{k-1}\). On the other hand, the columns of \(P\) are \({\mathbb{R}}\)-linearly independent, so \(S \cap {\mathbb{R}}^{k-1} = \{0\}\). Therefore, one has \(S \cap \overline{S} = \{0\}\), and so \(\dim_{{\mathbb{C}}} (\overline{S} \oplus S) = 2(k-1-r)\). Finally, we observe that \((W \cap {\mathbb{R}}^{k-1}) \otimes {\mathbb{C}} = W \cap \overline{W}\); as this satisfies
    \begin{equation*}
         W \cap \overline{W} =  \overline{S}^\perp \cap  S^\perp  = (\overline{S} \oplus S)^\perp,
    \end{equation*}
    then,
    \begin{align*}
        \dim_{{\mathbb{R}}} (W \cap {\mathbb{R}}^{k-1}) &= \dim_{{\mathbb{C}}} (W \cap {\mathbb{R}}^{k-1}) \otimes {\mathbb{C}} = \dim_{{\mathbb{C}}} (W \cap \overline{W}) = \dim_{{\mathbb{C}}} (\overline{S} \oplus S)^\perp\\
        &= k-1 - 2(k-1-r) = 2 \dim_{{\mathbb{C}}} W - k +1. \qedhere
    \end{align*}

The proof consists of several steps:
    \paragraph{Step 1}
    By construction, \(N\) is the quotient of \(\mathbb{P}(U(\mathcal{T}))\) by the \({\mathbb{C}}^m\)-action \(\alpha\) defined in \zcref{equation:LVMBaction}. If \(\pi : \mathbb{P}(U(\mathcal{T})) \to N\) is the holomorphic projection on the orbit space, we can observe that the inverse image sheaf \(\pi^{-1}\mathcal{M}_N\) is the subsheaf of \(\mathcal{M}_{\mathbb{P}(U(\mathcal{T}))}\) consisting of local sections that are \(\alpha\)-invariant meromorphic functions on \(\mathbb{P}(U(\mathcal{T}))\); we denote it by \(\mathcal{M}_{\mathbb{P}(U(\mathcal{T}))}^\alpha\). Moreover, since \(\pi\) is a surjective holomorphic submersion with connected fibers, we have \(\mathcal{M}_N \cong \pi_*\mathcal{M}_{\mathbb{P}(U(\mathcal{T}))}^\alpha \). In particular, for global sections, this isomorphism reads as
    \begin{equation*}
        \mathcal{M}_{N}(N)/{\mathbb{C}} \cong \mathcal{M}_{\mathbb{P}(U(\mathcal{T}))}^\alpha(\mathbb{P}(U(\mathcal{T})))/{\mathbb{C}};
    \end{equation*}
    and therefore the algebraic dimension of \(N\) coincides with the transcendence degree of the second extension.

    Since we are assuming \(k \geq 1\), we have \(\mathbb{P}(U(\mathcal{T})) = \mathbb{P}(({\mathbb{C}}^*)^k \times \tilde U)\). This is isomorphic to \(({\mathbb{C}}^*)^{k-1} \times \tilde U\), so we may restrict the action to this subset and seek invariant meromorphic functions thereon; this is achieved by choosing a representative in \([\Lambda]_{\mathbb{C}}\) with \(\Lambda_1 = 0\) and projectivizing away the first coordinate of \(({\mathbb{C}}^*)^{k}\). We can observe that \(\tilde U = {\mathbb{C}}^{n-k} \setminus E\) and, by \zcref[S]{minimal_codimension_no_ghosts}, \(E\) is the union of Zariski closed subsets of codimension \(> 1\) in \({\mathbb{C}}^{n-k}\). By the E.~E.~Levi extension theorem (see e.g. \cite[Thm 1.1]{HarveyPolking1975} and the remark below), any meromorphic function on \(({\mathbb{C}}^*)^{k-1} \times \tilde U\) extends uniquely to \(({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k} \). Thus, the problem reduces to the computation of
    \begin{equation*}
        \operatorname{tr}\deg \mathcal{M}_{({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k}}(({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k})^\alpha/{\mathbb{C}}.
    \end{equation*}

    \paragraph{Step 2} Since \(({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k}\) is a domain of holomorphy, any \(\alpha\)-invariant meromorphic function \(h\) on \(({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k}\) can be written as the quotient of two entire functions \(h = \frac{f}{g}\). On \(({\mathbb{C}}^*)^{k-1} \times {\mathbb{C}}^{n-k}\) we introduce the coordinates \((z,w)\) with \(z \in ({\mathbb{C}}^*)^{k-1}\) and \(w \in {\mathbb{C}}^{n-k}\).
    We consider the universal covering \({\mathbb{C}}^{k-1} \to ({\mathbb{C}}^*)^{k-1}\) given on each factor as \(\zeta_j \mapsto e^{2\pi i \zeta_j}\). Thus, the meromorphic lift \(\tilde h\) of \(h\) can be written as the quotient of two entire functions \(\tilde h = \frac{\tilde f}{\tilde g}\). Since \(\operatorname{Pic}({\mathbb{C}}^{k-1} \times {\mathbb{C}}^{n-k})=\{0\}\), \(\tilde f\) and \(\tilde g\) can be chosen without common zero loci. Similarly, we consider the lift of the action \(\alpha\) to the universal covering, this is an action which on each coordinate writes as

    \begin{align*}
        \tilde \alpha : {\mathbb{C}}^m \times ({\mathbb{C}}^{k-1} \times {\mathbb{C}}^{n-k}) &\longrightarrow {\mathbb{C}}^{k-1} \times {\mathbb{C}}^{n-k}\\
        t.(\zeta_j,w_\ell) &\longmapsto (\zeta_j + \langle L_j, t\rangle , e^{2\pi i \langle M_\ell,t\rangle} w_\ell),
    \end{align*}
    where \(\Lambda = (L,M)\) is a partitioning of the points in \(\Lambda\) collecting the indispensable points in \(L = (\Lambda_2,\dots, \Lambda_{k})\) and the remaining ones in \(M = (\Lambda_{k+1},\dots, \Lambda_{n})\). Notice that, having contracted the first coordinate of \(({\mathbb{C}}^*)^k\), the first indispensable point in \(L\) is \(\Lambda_2\). Since \(\tilde h\) lifts \(h\) and the latter is \(\alpha\)-invariant, \(\tilde h\) is invariant under the lifted action \(\tilde \alpha\) and also under the action of the deck transformation group \(\Gamma = {\mathbb{Z}}^{k-1}\). These actions clearly commute. Therefore, for any \(t \in {\mathbb{C}}^m\),
    \begin{equation*}
        \frac{t\cdot \tilde f}{t \cdot \tilde g} = t\cdot \tilde h = \tilde h = \frac{\tilde f}{\tilde g};
    \end{equation*}
    and thus, again using the fact that \(\operatorname{Pic}({\mathbb{C}}^{k-1} \times {\mathbb{C}}^{n-k})=\{0\}\), there exists a holomorphic function \(\psi_t(\zeta,w)\) such that
    \begin{equation}
    \label{LVMB_invariance}
        (t\cdot \tilde f)(\zeta,w) = e^{\psi_t(\zeta,w)} \tilde f(\zeta,w) \qquad (t\cdot \tilde g)(\zeta,w) = e^{\psi_t(\zeta,w)} \tilde g(\zeta,w).
    \end{equation}
    Similarly, the invariance of \(\tilde h\) under the covering action of \(\Gamma\) forces \(\tilde f\) and \(\tilde g\) to transform as
    \begin{equation}
    \label{deck_invariance}
        \tilde f(\zeta + \gamma,w) = e^{\varphi_\gamma(\zeta)} \tilde f(\zeta,w) \qquad \tilde g(\zeta + \gamma,w) = e^{\varphi_\gamma(\zeta)} \tilde g(\zeta,w),
    \end{equation}
    for some holomorphic function \(\varphi_\gamma(\zeta)\) depending on \(\gamma \in \Gamma\).
    \paragraph{Step 3}
    Upon multiplying both \(\tilde f\) and \(\tilde g\) by the same unit \(u \in \mathcal{O}^*({\mathbb{C}}^{n-1})\), we claim that \(\psi_t(\zeta,w) = \psi_t\). Such a \(u\) can be found by solving a linear PDE involving the fundamental vector fields of the action \(\tilde \alpha\). Indeed, with respect to the coordinates \((\zeta,w)\), these are the holomorphic vector fields
    \begin{equation*}
        \xi_j = \sum_{\ell=1}^{k-1} L_{\ell}^j \frac{\partial}{\partial\zeta_\ell} + \sum_{i=1}^{n-k} M_{i}^j w_i \frac{\partial}{\partial w_i}.
    \end{equation*}
    Thus, any \(\tilde\alpha\)-invariant meromorphic function \(\tilde h = \frac{\tilde f}{\tilde g}\) fulfills \(\xi_j(\tilde h) = 0\) for all \(j = 1,\dots, m\), and so \(\xi_j(\tilde f) \tilde g = \tilde f \xi_j(\tilde g)\). Since \(\tilde f\) and \(\tilde g\) have been chosen without common zero loci, this condition forces \(\tilde f | \xi_j(\tilde f)\), hence there exists \(q_j(\zeta,w) \in \mathcal{O}({\mathbb{C}}^{n-1})\) such that \(\xi_j(\tilde f) = \tilde f q_j(\zeta,w)\). Similarly, we also have \(\xi_j(\tilde g) = \tilde g q_j(\zeta,w)\). As the acting group is abelian, \([\xi_i,\xi_j]=0\) for all \(i\) and \(j\); thus
    \begin{equation*}
        \xi_i(q_j) = \xi_i \left(\frac{\xi_j(\tilde f)}{\tilde f}\right) = \frac{\xi_i(\xi_j(\tilde f)) - \xi_i(\tilde f) \xi_j(\tilde f)}{\tilde f^2} = \dots = \xi_j \left(\frac{\xi_i(\tilde f)}{\tilde f}\right) = \xi_j(q_i).
    \end{equation*}
    As we did before, the point configuration \(\Lambda\) can be thought as the block matrix
    \begin{equation*}
        \Lambda =
        \begin{bmatrix}
            L\\
            M
        \end{bmatrix}
        =
        \begin{bNiceMatrix}[margin]
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} L_1 \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}\\
            \vdots\\
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} L_{k-1} \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}\\
            \hline
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} M_1 \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}\\
            \vdots\\
            \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex} M_{n-k} \hspace{.5ex}\rule[.5ex]{2.5ex}{0.5pt}\hspace{.7ex}
        \end{bNiceMatrix}
        =
        \begin{bNiceMatrix}[margin]
            \rule[-1ex]{0.5pt}{2.5ex} & & \rule[-1ex]{0.5pt}{2.5ex} \\
            L^{1} & \cdots & L^{m} \\
            \rule[-1ex]{0.5pt}{2.5ex} & & \rule[-1ex]{0.5pt}{2.5ex}\\[1ex]
            \hline\vspace{.5ex}
            \rule[-1ex]{0.5pt}{2.5ex} & & \rule[-1ex]{0.5pt}{2.5ex} \\
            M^{1} & \cdots & M^{m} \\
            \rule[-1ex]{0.5pt}{2.5ex} & & \rule[-1ex]{0.5pt}{2.5ex}\\
        \end{bNiceMatrix}   
    \end{equation*}
    and, by \zcref[S]{dim_W}, the vector space \(W = \operatorname{Span}_{{\mathbb{C}}}(L^1,\dots, L^{m})\) has dimension \(\dim_{\mathbb{C}} W \eqqcolon r \leq \min(m,k-1)\). Since the \(L^j\)'s might not be linearly independent, we reparametrize \({\mathbb{C}}^m\) so that  \(\{L'^1,\dots,L'^r\}\) forms a basis of \(W\) and \(L'^{r+1},\dots, L'^{m} = 0\). We denote by \(M'^j\) the other vectors after the change of basis. Moreover, by performing a linear change of coordinates on \({\mathbb{C}}^{k-1}\), we can find new coordinates \(\zeta'_j\) such that \(\sum_{\ell=1}^r L'^j_\ell \frac{\partial}{\partial \zeta_\ell} = \frac{\partial}{\partial\zeta_j'}\) for \(1\leq j \leq r\) and \(\frac{\partial}{\partial \zeta_j} = \frac{\partial}{\partial\zeta_j'}\) for \(r < j \leq k-1\). With respect to these changes of coordinates, the fundamental vector fields are of the form
    \begin{equation*}
        \xi'_j =
        \begin{cases}
            \frac{\partial}{\partial\zeta_j'} + \sum_{i=1}^{n-k} {M'}_{i}^j w_i \frac{\partial}{\partial w_i} & 1 \leq j \leq r\\
            \sum_{i=1}^{n-k} {M'}_{i}^j w_i \frac{\partial}{\partial w_i} & r+1 \leq j\leq m.
        \end{cases}
    \end{equation*}

    The unit \(u(\zeta',w) = e^{v(\zeta',w)}\) we need is a solution of the following PDE
    \begin{equation}
        \label{equation:unit_equation}
        \frac{\xi_j'(\tilde f u)}{\tilde f u} = c_j
    \end{equation}
    for some constants \(c_j \in {\mathbb{C}}\). Equivalently, we can solve
    \begin{equation}
        \label{equation:log_unit_equation}
        \xi_j'(v) = c_j - q_j(\zeta',w).
    \end{equation}
    Being holomorphic, \(q_j(\zeta',w)\) and \(v(\zeta',w)\) can be expanded in power series as
    \begin{equation*}
        q_j(\zeta',w) = \sum_{J} p_{jJ}(\zeta') w^J,\quad v(\zeta',w) = \sum_{I} \nu_I(\zeta') w^I.
    \end{equation*}
    Observe that for any multi-index \(I\), one has \(w_j \frac{\partial}{\partial w_j} (w^I) = I_j w^I\), thus the PDE
    \begin{equation*}
        \xi_j'\left(\sum_I \nu_I(\zeta') w^I\right) = \xi_j'(v) = c_j - q_j(\zeta',w) = c_j - \sum_{J} p_{jJ}(\zeta') w^J 
    \end{equation*}
    reduces to the following equations by comparing the corresponding terms in the power series expansions. Namely, these are
    \begin{equation*}
        \begin{cases}
                \frac{\partial\nu_I}{\partial \zeta'_j} + \varepsilon_{I,j} \nu_I(\zeta') = -p_{j,I}(\zeta') & I \neq 0\\
                \frac{\partial\nu_0}{\partial \zeta'_j} = c_j - p_{j,0}(\zeta') & I=0\\ 
        \end{cases}
        \quad \text{for } j \leq r, \tag{\dag}
    \end{equation*}
    while for \(j > r\) one gets the algebraic equations
    \begin{equation*}
        \begin{cases}
            \varepsilon_{I,j} \nu_I(\zeta') = -p_{j,I}(\zeta') & I \neq 0\\
            0 = c_j - p_{j,0}(\zeta') & I=0\\
        \end{cases}
        \quad \text{for } r<j\leq m. \tag{\ddag}
    \end{equation*}
    In both groups we have collected the term \(\varepsilon_{I,j} \coloneqq \sum_{i=1}^{n-k}{M'}_i^j I_i\).


    We first take into account the equations \((\ddag)\). We notice that \(p_{j,0}(\zeta') = c_j\) is a twofold constraint. Of course, it determines the values for \(c_j\) when \(j > r\), but also forces \(p_{j0}(\zeta')\) to be constant for \(j > r\). However, this is precisely what occurs here, due to the rigidity of the condition \(\xi_j'(\tilde f) = \tilde f q_j\). Indeed, since for \(j > r\) the vector field \(\xi_j'\) acts as a scaling with respect to the coordinates we have chosen, this condition reads as
    \begin{equation*}
        \sum_{|I| \geq b} \varepsilon_{j,I} \tilde f_I(\zeta') w^I = \left(p_{j,0}(\zeta') + \sum_{J >0} p_{j,J}(\zeta') w^J \right) \left(\sum_{|I| \geq b}  \tilde f_I(\zeta') w^I \right),
    \end{equation*}
    where \(b\) is the lowest total degree such that \(f_I(\zeta') \not\equiv 0\) for some \(|I| = b\). Comparing all the terms of total degree \(b\), we have then
    \begin{equation*}
        \varepsilon_{j,I} \tilde f_I(\zeta') = p_{j,0}(\zeta') \tilde f_I(\zeta') \quad \forall |I| = b.
    \end{equation*}
    If \(I^*\) is any multi-index of total degree \(b\) such that \(f_{I^*}(\zeta') \not\equiv 0\), the equation above then forces \(p_{j,0}(\zeta') = \varepsilon_{I^*,j}\) which proves the constancy of \(p_{j,0}\) for \(j>r\). In turn, this implies that \(\varepsilon_{I,j} = \varepsilon_{I^*,j}\) for any \(I\) such that \(f_I(\zeta') \not\equiv 0\). Even though for \(j \leq r\) we could perform any choice for \(c_j\), for simplicity we henceforth fix \(c_j = p_{j,0}(0)\) for any \(j\). Moreover, if \(\varepsilon_{I;j} = 0\) for some \(I \neq 0\), the condition \(p_{j;I}(\zeta') = 0\), which must necessarily hold, is already a consequence of \zcref{equation:log_unit_equation}.

    The equations appearing in \((\dag)\) are genuinely PDEs, to solve them we introduce the conformal substitutions.
    \begin{equation*}
        \mu_I(\zeta') = e^{\sum_{j=1}^r \varepsilon_{I,j} \zeta_j'}\nu_I(\zeta').
    \end{equation*}
    Thus, for \(j \leq r\), the PDEs read as
    \begin{equation*}
        \begin{cases}
        \frac{\partial \mu_I}{\partial \zeta'_j} = - e^{\sum_{j=1}^m \varepsilon_{I,j} \zeta_j'} p_{j,I}(\zeta') \eqqcolon - p'_{j,I}(\zeta') & \forall I \neq 0\\
        \frac{\partial\mu_0}{\partial \zeta'_j} = c_j - p_{j,0}(\zeta') & I=0;
        \end{cases}
    \end{equation*}
    indeed, \(p'_{j,0}(\zeta') = p_{j,0}(\zeta')\) since \(\varepsilon_{0,j} = 0\) for every \(j =1,\dots,m\). We define the family of holomorphic \(1\)-forms in the variables \(\zeta'_1,\dots,\zeta'_r\)
    \begin{equation*}
        \begin{cases}
            \omega_I = - \sum_{j=1}^r p'_{j,I}(\zeta') d\zeta_j' & I \neq 0\\
            \omega_0 = \sum_{j=1}^r (c_j - p'_{j,0}(\zeta')) d\zeta_j' & I = 0
        \end{cases}
    \end{equation*}
    whose coefficients are holomorphic functions in the whole set of coordinates \(\zeta'_1, \dots, \zeta'_{k-1}\). The condition \(\xi_j(q_i) = \xi_i(q_j)\) implies that, in the new coordinates, \(\frac{\partial p'_{jI}}{\partial \zeta_i'} = \frac{\partial p'_{iI}}{\partial \zeta_j'}\) for every \(1 \leq i,j \leq k-1\) and every multi-index \(I\). If \(d_{\leq r}\) denotes the differential with respect to the first \(r\) variables, we can observe that the last condition is equivalent to \(d_{\leq r}\omega_I = 0\) for every \(I\). Therefore, the Poincaré Lemma with parameters (see e.g. \cite[\S VII.3]{BerhanuCordaroHounie2008}) guarantees the existence of a function
    \begin{equation*}
        \mu_I(\zeta') =  \mu_I'(\zeta') + \eta_I(\zeta'_{r+1},\dots, \zeta'_{k-1})
    \end{equation*}
    which fulfills \(d_{\leq r} \mu_I' = \omega_I\) and which is holomorphic in the last \(k-1-r\) coordinates. In fact, as \(\omega\) is of type \((1,0)\), \({\bar\partial}_{\leq r} \mu_I=0\). After reverting the conformal substitution, we find solutions \(\nu_I(\zeta')\) uniquely determined up to the addition of a holomorphic function \(\eta'_I\).

    Whenever the ratio \(\frac{p_{jI}}{\varepsilon_{I,j}}\) can be defined, it is independent of \(j\) by the compatibility condition \(\xi_j'(q_i) = \xi_i'(q_j)\). These ratios determine the corresponding \(\eta_I\)'s: imposing \(\nu_I\) to be a solution of \((\ddag)\) indeed forces
    \begin{equation*}
        \eta'_I = - \left(\frac{p_{jI}}{\varepsilon_{I,j}} + \nu_I\right).
    \end{equation*}


    Finally, we show that the determination of \(\eta'\) provided by \((\ddag)\) does not affect the PDE in \((\dag)\). This is trivial if \(\varepsilon_{I,j} = 0\), otherwise this is another consequence of the identity \(\xi_j'(q_i) = \xi_i'(q_j)\). Indeed, for \(i \leq r < j\)
    \begin{align*}
        \frac{\partial}{\partial\zeta'_i} \left(-\frac{p_{j,I}}{\varepsilon_{I,j}}\right) - \varepsilon_{I,i} \frac{p_{j,I}}{\varepsilon_{I,j}} &= -\frac{1}{\varepsilon_{I,j}} \left(\frac{\partial p_{j,I}}{\partial\zeta'_i} + \varepsilon_{I,i} p_{j,I}\right)\\
        &= -\frac{1}{\varepsilon_{I,j}}\left(\xi'_i(q_j)\right)_I\\
        &= -\frac{1}{\varepsilon_{I,j}}\left(\xi'_j(q_i)\right)_I\\
        &= -\frac{1}{\varepsilon_{I,j}} (\varepsilon_{I,j} p_{i,I}) = - p_{i,I}.
    \end{align*}

    Therefore, the unit \(u \in \mathcal{O}^*({\mathbb{C}}^{n-1})\) solving \zcref{equation:unit_equation} can be obtained by integrating \zcref{equation:log_unit_equation} along the flow of the \(\xi_j\)'s. In particular, \(\psi_t(\zeta,w)\) can be reduced to the pure character
    \begin{equation*}
        \psi_t = \sum_{j=1}^m c_j t_j : {\mathbb{C}}^m \to {\mathbb{C}}.
    \end{equation*}
    \paragraph{Step 4}
    \zcref[S]{LVMB_invariance,deck_invariance} impose some constraints on the power series expansion of \(\tilde f\) and \(\tilde g\). In general, these have the following form:
    \begin{equation*}
        \tilde f(\zeta,w) = \sum_{J \in \mathbb{N}^{n-k}} c_J(\zeta) w^J, \qquad \tilde g(\zeta,w) = \sum_{J \in \mathbb{N}^{n-k}} d_J(\zeta) w^J.
    \end{equation*}
    Comparing the \(J\)'th terms, \zcref[S]{deck_invariance} implies
    \begin{equation*}
        c_J(\zeta + \gamma) = e^{\varphi_\gamma(\zeta)} c_J(\zeta), \qquad d_J(\zeta + \gamma) = e^{\varphi_\gamma(\zeta)} d_J(\zeta)
    \end{equation*}
    for every \(J\). Furthermore, \zcref[S]{LVMB_invariance} forces the power series expansion of \(\tilde f\) to fulfill
    \begin{equation}
        \label{condition_on_power_series}
        \sum_{J \in \mathbb{N}^{n-k}} c_J(\zeta + L t) e^{2\pi i \langle J; M,t\rangle} w^J = e^{\psi_t} \sum_{J \in \mathbb{N}^{n-k}} c_J(\zeta) w^J,
    \end{equation}
    where we have adopted the notations \(\langle J;M,t\rangle \coloneqq \sum_{\ell =1}^{n-k} J_\ell \langle M_\ell, t \rangle\) and \(L t \coloneqq \sum_{j=1}^m L^j t_j\). Therefore, \zcref{condition_on_power_series} holds if and only if, for any \(J\),
    \begin{equation}
        \label{coefficients_resonance}
        c_J(\zeta +  L t) = e^{\psi_t - 2\pi i\langle J; M,t \rangle} c_J(\zeta).
    \end{equation}

    Without loss of generality, we may assume \(\tilde f\) does not to vanish identically; in this case we choose a reference multi-index \(J_0\) such that \(c_{J_0}(\zeta)\) is not identically zero. Therefore, we can rewrite \(\tilde h\) as
    \begin{equation*}
        \frac{\tilde f}{\tilde g} = \frac{\sum_{J} c_J(\zeta) w^J}{\sum_J d_J(\zeta)  w^J} = \frac{\frac{1}{c_{J_0}(\zeta)}\sum_{J} c_J(\zeta) w^J}{\frac{1}{c_{J_0}(\zeta)}\sum_J d_J(\zeta)  w^J} \eqqcolon \frac{\sum_{J} r_J(\zeta) w^J}{\sum_J s_J(\zeta)  w^J},
    \end{equation*}
    where, \(r_J(\zeta) = \frac{c_J(\zeta)}{c_{J_0}(\zeta)}\) and \(s_J(\zeta) = \frac{d_J(\zeta)}{c_{J_0}(\zeta)}\). These functions have the advantage of being \(\Gamma\)-invariant, indeed
    \begin{align*}
        r_J(\zeta + \gamma) &= \frac{e^{\varphi_\gamma(\zeta)} c_J(\zeta)}{e^{\varphi_\gamma(\zeta)}c_{J_0}(\zeta)} = r_J(\zeta),\\
        s_J(\zeta + \gamma) &= \frac{e^{\varphi_\gamma(\zeta)} d_J(\zeta)}{e^{\varphi_\gamma(\zeta)}c_{J_0}(\zeta)} = s_J(\zeta).
    \end{align*}
    This means that \(r_J\) and \(s_J\) descend to meromorphic functions on \(({\mathbb{C}}^*)^{k-1}\). Since this is a domain of holomorphy, these are ratios of entire functions; moreover, as the domain is a multi-annulus, they can be written as ratios of convergent Laurent series. With respect to the coordinates \(\zeta_j\), their expansions are
    \begin{equation*}
        r_J(\zeta) = \frac{\sum_{I \in {\mathbb{Z}}^{k-1}} \rho_{JI} e^{2\pi i \langle I,\zeta \rangle}}{\sum_{I' \in {\mathbb{Z}}^{k-1}} \rho'_{JI'} e^{2\pi i \langle I',\zeta \rangle}}, \qquad s_J(\zeta) = \frac{\sum_{I \in {\mathbb{Z}}^{k-1}} \sigma_{JI} e^{2\pi i \langle I,\zeta \rangle}}{\sum_{I' \in {\mathbb{Z}}^{k-1}} \sigma'_{JI'} e^{2\pi i \langle I',\zeta \rangle}}.
    \end{equation*}
    We now examine how these expressions transform under the action of \(\tilde \alpha\) restricted to the first \(k-1\) coordinates, we can observe that \(r_J\)'s (and similarly \(s_J\)'s) fulfill the equation
    \begin{align*}
        r_J(\zeta + L t) &= \frac{c_J(\zeta + L t)}{c_{J_0}(\zeta + L t) } = \frac{e^{\psi_t - 2\pi i\langle J; M,t \rangle} c_J(\zeta)}{e^{\psi_t - 2\pi i\langle J_0; M,t \rangle} c_{J_0}(\zeta)}\\
        &=e^{2\pi i\langle J_0 - J; M,t \rangle} \frac{c_J(\zeta)}{c_{J_0}(\zeta)}= e^{2\pi i\langle J_0 - J; M,t \rangle} r_J(\zeta).
    \end{align*}
    Therefore, for any \(J\), one has
    \begin{align*}
        \frac{\sum_{I\in {\mathbb{Z}}^{k-1}} \rho_{JI} e^{2\pi i \langle I,\zeta\rangle} e^{2\pi i \langle I;L,t\rangle}}{\sum_{I'\in {\mathbb{Z}}^{k-1}} \rho'_{JI'} e^{2\pi i \langle I',\zeta\rangle} e^{2\pi i \langle I';L,t\rangle}} &= r_J(\zeta + L t) = e^{2\pi i \langle J_0-J;M,t\rangle} r_J(\zeta)\\
        &= e^{2\pi i \langle J_0-J;M,t\rangle} \frac{\sum_{I\in {\mathbb{Z}}^{k-1}} \rho_{JI} e^{2\pi i \langle I,\zeta\rangle}}{\sum_{I'\in {\mathbb{Z}}^{k-1}} \rho'_{JI'} e^{2\pi i \langle I',\zeta\rangle}},
    \end{align*}
    which can be written in a single line as
    \begin{equation*}
        \sum_{I,I'} \rho_{JI}\rho'_{JI'} e^{2\pi i \langle I +I', \zeta\rangle} e^{2\pi i \langle I;L,t\rangle} = e^{2\pi i \langle J_0-J;M,t\rangle} \sum_{I,I'} \rho_{JI} \rho'_{JI'} e^{2\pi i \langle I+I',\zeta\rangle} e^{2\pi i \langle I';L,t\rangle},
    \end{equation*}
    for all \(t \in {\mathbb{C}}^m\). This holds if and only if, for any \(\hat I \in {\mathbb{Z}}^{k-1}\),
    \begin{equation*}
        \sum_{I+I' = \hat I} \rho_{JI}\rho'_{JI'} e^{2\pi i \langle I;L,t\rangle} = e^{2\pi i \langle J_0-J;M,t\rangle} \sum_{I+I' = \hat I} \rho_{JI}\rho'_{JI'} e^{2\pi i \langle I';L,t\rangle}.
    \end{equation*}
    Since exponentials with different frequencies are linearly independent, the non-vanishing terms are precisely those satisfying
    \begin{equation}
    \label{fundamental_equation}
        \sum_{j=1}^{k-1} (I_j - I'_j) L_j + \sum_{\ell=1}^{n-k} J_\ell M_\ell = \lambda
    \end{equation}
    for some \(\lambda \in {\mathbb{C}}^m\) depending on \(J_0\) and \(M\). From this, we deduce that \(r_J(\zeta)\) does not vanish identically only if there exists \(I_J\) such that the pair \((I_J,J) \in (0,J_0) + I(\Lambda)\); for any such \(r_J(\zeta)\), we consider the rescaling
    \begin{equation*}
        \hat r_J(\zeta) = \frac{r_J(\zeta)}{e^{2\pi i\langle I_J,\zeta\rangle}}
    \end{equation*}
    which is \(\tilde \alpha\)-invariant and meromorphic. Proceeding similarly for the functions \(s_J\), we can write
    \begin{equation}
        \label{intermediate_expression}
        \tilde f(\zeta,w) = \sum_J \hat r_J(\zeta) e^{2\pi i \langle I_J,\zeta\rangle} w^J, \qquad \tilde g(\zeta,w) = \sum_J \hat s_J(\zeta) e^{2\pi i \langle I_J,\zeta\rangle} w^J
    \end{equation}
    where \(\hat r_J(\zeta)\) are invariant under the action of the product \(\Gamma \times {\mathbb{C}}^m\), and \(e^{2\pi i \langle I_J,\zeta\rangle} w^J = z^{I_J} w^J\) are resonant Laurent monomials.

    \paragraph{Step 5}
    For any \(\lambda \in {\mathbb{C}}^m\), the set of solutions of \zcref[S]{fundamental_equation} is
    \begin{equation*}
        S_\lambda = \{ (I,J) \in {\mathbb{Z}}^{k-1} \times \mathbb{N}^{n-k} : (I,J-J_0) \in I(\Lambda)\}.
    \end{equation*}
    By the geometry of the LVMB datum, this is finite. Indeed, \(S_\lambda\) is a discrete subset of \((J_0 + \operatorname{Rel}(\Lambda)) \cap ({\mathbb{R}}^{k-1} \times {\mathbb{R}}^{n-k}_{\geq 0})\), which is compact by \zcref[S]{compact_intersection}. This also implies that for any \(J\) there exist only finitely many multi-indexes \(I_J\) such that \((I_J,J) \in S_\lambda\).
    \paragraph{Step 6}
    For any \(K \in {\mathbb{Z}}^{n-1}\) we associate the Laurent monomial
    \begin{equation*}
        \operatorname{\mathcal{L}}(K) = \prod_{j=1}^{k-1} z_j^{K_{j}} \cdot \prod_{j=1}^{n-k} w_j^{K_{j}};
    \end{equation*}
    this defines a map \(\operatorname{\mathcal{L}} : {\mathbb{Z}}^{n-1} \to {\mathbb{C}}[{\mathbb{Z}}^{n-1}]\), that is the canonical injection of \({\mathbb{Z}}^{n-1}\) into its group \({\mathbb{C}}\)-algebra \cite[II.\S 3]{Lang2002}. In particular, for any linearly independent set \(\{K^1,\dots,K^{s}\} \subset {\mathbb{Z}}^{n-1}\), its image \(\{\operatorname{\mathcal{L}}(K^1),\dots, \operatorname{\mathcal{L}}(K^s)\}\) is algebraically independent in \({\mathbb{C}}(\{z_i, w_j\}_{i,j})\).



    This fact gives us a natural basis with respect to which writing the resonant Laurent monomials in \zcref[S]{intermediate_expression}: indeed, since any \(K \in S_\lambda\) can be uniquely written as \(K = (0,J_0) + \kappa_K\) with \(\kappa_K \in I(\Lambda)\), this determines the Laurent monomial
    \begin{equation*}
        \operatorname{\mathcal{L}}(K) = \operatorname{\mathcal{L}}(J_0) \operatorname{\mathcal{L}}(\kappa_K),
    \end{equation*}
    which is the product of the first integral Laurent monomial \(\operatorname{\mathcal{L}}(\kappa_K)\) (cf. \cite{GrašičJarrahRomanovski2025}) with a fixed monomial \(\operatorname{\mathcal{L}}(J_0)\) in the coordinates \(w_j\). Moreover, if \((\kappa^1,\dots, \kappa^a)\) is a \({\mathbb{Z}}\)-basis of \(I(\Lambda)\), any \(\operatorname{\mathcal{L}}(K)\) is of the form
    \begin{equation*}
        \operatorname{\mathcal{L}}(K) = \operatorname{\mathcal{L}}(J_0) \operatorname{\mathcal{L}}(\kappa^1)^{\mu_1}\cdots \operatorname{\mathcal{L}}(\kappa^a)^{\mu_a}
    \end{equation*}
    for some \(\mu_j \in {\mathbb{Z}}\). Therefore, \(\tilde f\) and \(\tilde g\) can be expressed as the \emph{finite} sums
    \begin{equation*}
        \tilde f = \sum_{K \in S_\lambda} \hat r_{K}(\zeta) \operatorname{\mathcal{L}}(K), \quad \tilde g = \sum_{K \in S_\lambda} \hat s_{K}(\zeta) \operatorname{\mathcal{L}}(K),
    \end{equation*}
    and each \(\operatorname{\mathcal{L}}(K)\) is a finite product of the first integral Laurent monomials \(\operatorname{\mathcal{L}}(\kappa^j)\) times a fixed \(\operatorname{\mathcal{L}}(J_0)\). Therefore, we have written \(\tilde h\) as the rational expression
    \begin{equation}
        \label{final_rational_expression}
        \tilde h = \frac{\sum_{\kappa \in S_\lambda - J_0} \hat r_{\kappa + J_0}(\zeta) \operatorname{\mathcal{L}}(\kappa)}{\sum_{{\kappa \in S_\lambda - J_0}} \hat s_{\kappa+J_0}(\zeta) \operatorname{\mathcal{L}}(\kappa)}
    \end{equation}
    with coefficients in the field of \(\alpha\)-invariant meromorphic functions on \(({\mathbb{C}}^*)^{k-1}\).

    \paragraph{Step 7}
    As observed in Step 2, the coefficients of the last rational expression lift to meromorphic functions on \({\mathbb{C}}^{k-1}\); their lift is invariant under the restriction of \(\tilde\alpha\) to \({\mathbb{C}}^{k-1}\), as well as under the deck action of \(\Gamma\). As we observed in Step 2 these actions commute. With respect to the coordinates of the covering \(\zeta_j\)'s, the product of these actions coincides with the translation along the subgroup
    \begin{equation*}
        W + \Gamma = \operatorname{Span}_{{\mathbb{C}}}\{L^1,\dots, L^m\} + \Gamma
        \subseteq {\mathbb{C}}^{k-1}.
    \end{equation*}
    By \zcref[S]{dim_W}, \(\dim_{{\mathbb{C}}}W \leq \min(m,k-1)\). Note that the subgroup \(W + \Gamma \subset {\mathbb{C}}^{k-1}\) is not closed in general; consequently the orbits of the combined action of \(\tilde\alpha\) and the deck transformations \(\Gamma\) may fail to be separated. Let \(\mathcal{M}^{W + \Gamma}\) be the set of meromorphic functions of \({\mathbb{C}}^{k-1}\) invariant under the translation by \(W + \Gamma\). We consider the following complex vector subspace
    \begin{equation*}
        K = \bigcap_{f \in \mathcal{M}^{W + \Gamma}} \{v \in {\mathbb{C}}^{k-1} : df(v) \equiv 0\} \subseteq {\mathbb{C}}^{k-1}
    \end{equation*}
    consisting of all vectors along which the directional derivative of all meromorphic functions in \(\mathcal{M}^{W + \Gamma}\) vanishes. We claim that \(K\) is the connected component containing the identity of \(\overline{K+\Gamma}\). Indeed, by definition of \(K\), any \(f \in \mathcal{M}^{W+\Gamma}\) is invariant under translation by \(K + \Gamma\); being meromorphic, \(f\) is invariant under translation by the whole \(\overline{K + \Gamma}\). Thus, when we take directional derivatives, we find \(df(v) \equiv 0\) for any \(v\) in the connected component of \(\overline{K + \Gamma}\) containing the identity. Since \(K\) contains all the subspaces with this property, \(K = (\overline{K + \Gamma})^0\). Therefore, by the classification theorem of closed subgroups of \({\mathbb{R}}^{2k-2}\) \cite[VII.\S 1.2]{Bourbaki1989GenTopChapters5-10}, there exists a finitely generated subgroup \(\Gamma_0\) such that \(\overline{K + \Gamma} = K \oplus \Gamma_0\). Since \(K \oplus \Gamma_0 \supseteq W + \Gamma\), we have \(K \oplus (\Gamma_0 \otimes {\mathbb{R}}) \supseteq W + (\Gamma \otimes {\mathbb{R}})\); therefore, by \zcref[S]{dim_W},
    \begin{align*}
        \dim_{\mathbb{R}} (K \oplus (\Gamma_0 \otimes {\mathbb{R}}) ) &\geq \dim_{\mathbb{R}} (W + (\Gamma \otimes {\mathbb{R}}) )\\
        &= \dim_{{\mathbb{R}}}W + k-1 - \dim_{{\mathbb{R}}}(W \cap {\mathbb{R}}^{k-1})\\
        &= 2\dim_{{\mathbb{C}}}W + k-1 - (2 \dim_{{\mathbb{C}}}W - k + 1)\\
        &= 2k-2,
    \end{align*}
    and so \(K \oplus (\Gamma_0 \otimes {\mathbb{R}}) = {\mathbb{C}}^{k-1}\). In particular, \(\Gamma_0\) projects onto a lattice in \({\mathbb{C}}^{k-1}/K\), hence
    \begin{equation*}
        \frac{{\mathbb{C}}^{k-1}/K}{\Gamma_0} = \mathbb{T}^q
    \end{equation*}
    is a complex torus such that \(\mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q) \cong \mathcal{M}^{W + \Gamma}\). One can verify that
    \begin{equation*}
        \dim_{\mathbb{C}} \mathbb{T}^{q} = q = k-1-\dim_{{\mathbb{C}}}K \leq k-1 - \dim_{{\mathbb{C}}}W \leq k - 1 - \left\lceil \frac{k-1}{2}\right\rceil = \left\lfloor \frac{k-1}{2} \right\rfloor.
    \end{equation*}
    \paragraph{Step 8}
    Since the first integral Laurent monomials are the images of \(I(\Lambda)\) under \(\operatorname{\mathcal{L}}\), by \zcref[S]{final_rational_expression} and the previous step,
    \begin{equation*}
        \mathcal{M}_{N}(N) \cong (\mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q))(\operatorname{\mathcal{L}}(\kappa): \kappa \in I(\Lambda)).
    \end{equation*}

    By \zcref[S]{compact_intersection}, any relation in \(\operatorname{Rel}(\Lambda)\) involves at least one non-indispensable index; hence any non-constant first integral Laurent monomial \(\operatorname{\mathcal{L}}(\kappa)\) depends explicitly on some of the coordinates \(w_j\)'s. On the other hand, the meromorphic functions of \(\mathbb{T}^q\) depend only on the coordinates \(\zeta_i\)'s, whose exponential is the set of coordinates \(z_i\)'s. Therefore, all non-constant monomials in \(\operatorname{\mathcal{L}}(I(\Lambda))\) are algebraically independent of the functions in \(\mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q)\). Thus,
    \begin{align*}
        \dim_{\mathrm{alg}}\!\left(N\right) &= \operatorname{tr}\deg \mathcal{M}_{N}(N)/{\mathbb{C}} = \operatorname{tr}\deg \mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q)/{\mathbb{C}} + \operatorname{tr}\deg \mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q)(\operatorname{\mathcal{L}}(I(\Lambda))) / \mathcal{M}_{\mathbb{T}^q}(\mathbb{T}^q)\\
        &= \dim_{\mathrm{alg}}\!\left(\mathbb{T}^q\right) + a(\Lambda) \leq \left\lfloor \frac{k-1}{2} \right\rfloor + a(\Lambda).
    \end{align*}
    In particular, for \(k \leq 2\), \(\dim_{\mathrm{alg}}\!\left(N\right) \leq a(\Lambda)\). Since by \zcref[S]{Meersseman_lower_bound} (i.e. \cite[Thm. 4]{Meersseman2000}) \(\dim_{\mathrm{alg}}\!\left(N\right) \geq a(\Lambda)\), with the equality when \(k=0\), we obtain \(\dim_{\mathrm{alg}}\!\left(N\right) = a(\Lambda)\) for any LVMB manifold \(N\) with \(k \leq 2\).

Let \(X\) be a compact complex manifold. A surjective holomorphic map \(\Psi_X : \widetilde{X} \to X^\text{red}\) is an algebraic reduction of \(X\) if
    \begin{itemize}
        \item \(\widetilde{X}\) is a modification of \(X\), i.e. a compact complex manifold \(\widetilde{X}\) with a holomorphic and bimeromorphic map \(\epsilon_X : \widetilde{X} \to X\),
        \item \(X^\text{red}\) is a  projective variety with \(\dim_{\mathbb{C}} X^\text{red} = \dim_{\mathrm{alg}}\!\left(X\right)\),
        \item \(\epsilon_X^* \circ \Psi_X^* : \mathcal{M}_{X^\text{red}}(X^\text{red}) \to \mathcal{M}_{X}(X)\) is a ring isomorphism.
    \end{itemize}

In the last step of the proof of \zcref[S]{algebraic_dimension_formula}, we showed that, if \(k\geq 1\),
    \begin{equation*}
        \mathcal{M}_{N}(N) \cong \mathcal{M}_{\mathbb{T}^{q}}(\mathbb{T}^{q})(\operatorname{\mathcal{L}}(I(\Lambda))),
    \end{equation*}
    with \(\operatorname{\mathcal{L}}(I(\Lambda)) = \{\operatorname{\mathcal{L}}(\kappa) : \kappa \in I(\Lambda)\}\) denoting the set of Laurent monomial arising from the first integrals of the LVMB configuration presented in Step 6. Moreover, the proof of \cite[Thm.~4]{Meersseman2000} shows that the same isomorphism holds also when \(k=0\); in this case \(q = 0\) automatically. Since the field extension \(\mathcal{M}_{N}(N)/\mathcal{M}_{\mathbb{T}^{q}}(\mathbb{T}^{q})\) is totally transcendental, \(\mathcal{M}_{N}(N)/{\mathbb{C}}\) is generated by the set
    \begin{equation*}
        \{g_1,\dots,g_\ell\} \cup \{\operatorname{\mathcal{L}}(\kappa_1), \dots, \operatorname{\mathcal{L}}(\kappa_{a(\Lambda)})\}
    \end{equation*}
    where \(\{g_1,\dots,g_\ell\}\) is a set of generators for \(\mathcal{M}_{\mathbb{T}^{q}}(\mathbb{T}^{q})/{\mathbb{C}}\) and \(\{\kappa_1,\dots, \kappa_{a(\Lambda)}\}\) is a basis for \(I(\Lambda)\). We now consider Ueno's map
    \begin{align*}
        \Phi_N^0 : N &\mathrel{
    \tikz[baseline]{\draw[dash pattern=on .25em off .1 em,->](0,.58ex)--(1.38 em,.58ex)}} \mathbb{C}\mathrm{P}^\ell \times \mathbb{C}\mathrm{P}^{a(\Lambda)}\\
        z &\longmapsto \left(\left(1:g_1(z) : \dots : g_\ell(z)\right), \left(1: \operatorname{\mathcal{L}}(\kappa_1)(z): \dots : \operatorname{\mathcal{L}}(\kappa_{a(\Lambda)})(z)\right)\right)
    \end{align*}
    which is dominant onto the second component \(\mathbb{C}\mathrm{P}^{a(\Lambda)}\), since \(\mathcal{M}_{N}(N)/\mathcal{M}_{\mathbb{T}^{q}}(\mathbb{T}^{q})\) is totally transcendental. On the other hand, since \(\{g_1,\dots,g_\ell\}\) generate \(\mathcal{M}_{\mathbb{T}^{q}}(\mathbb{T}^{q})/{\mathbb{C}}\), the projection \(\operatorname{pr}_1 \circ \Phi_N^0\) is dominant onto a possibly singular subvariety of \(\mathbb{C}\mathrm{P}^\ell\) which, by construction, is birationally equivalent to an abelian variety \(\mathbb{T}^{r}\) of dimension \(r \leq q \leq \left\lfloor \frac{k-1}{2} \right\rfloor\); namely the algebraic reduction of the torus \(\mathbb{T}^{q}\). After finitely many blowups that resolve the indeterminacy, we therefore obtain the algebraic reduction \(\Phi_N : \widetilde{N} \to \mathbb{T}^{r} \times \mathbb{C}\mathrm{P}^{a(\Lambda)}\).

Let \(\{e_j\}_j\) and \(\{e_j'\}_j\) be the canonical bases of \({\mathbb{R}}^n\) and \({\mathbb{R}}^{n'}\) respectively. Let \(\pi : {\mathbb{R}}^n \to {\mathbb{R}}^d\) be the map sending \(e_j \mapsto v_j\), and \(\pi' : {\mathbb{R}}^{n'} \to {\mathbb{R}}^d\) defined by \(e'_j \to w_j\). Then, by definition \(\operatorname{Rel}(V) = \ker \pi \subseteq {\mathbb{R}}^{n}\) and \(\operatorname{Rel}(V') = \ker\pi' \subseteq {\mathbb{R}}^{n'}\).
    We now show that, in our setting, the isomorphism provided by Schanuel's Lemma \cite[Lemma~11.28]{Faith1973} is rational. Consider the following commutative diagram with exact rows
    \begin{equation*}
        \begin{tikzcd}[column sep = large]
            0 \ar[r] & \operatorname{Rel}(V) \oplus {\mathbb{R}}^{n'} \ar[r,"\ker \pi \oplus \operatorname{id}"] & {\mathbb{R}}^n \oplus {\mathbb{R}}^{n'} \ar[r,"{(\pi,0)}"] & {\mathbb{R}}^d \ar[r] & 0\\
            0 \ar[r] & \ker(\pi + \pi') \ar[u] \ar[d] \ar[r] & {\mathbb{R}}^n \oplus {\mathbb{R}}^{n'} \ar[u,"F"'] \ar[d,"G"] \ar[r, "\pi + \pi'"] & {\mathbb{R}}^d \ar[u,equals] \ar[d,equals] \ar[r] & 0\\
            0 \ar[r] & {\mathbb{R}}^{n} \oplus \operatorname{Rel}(V') \ar[r, "\operatorname{id} \oplus \ker \pi'"] & {\mathbb{R}}^n \oplus {\mathbb{R}}^{n'} \ar[r,"{(0,\pi')}"] & {\mathbb{R}}^d \ar[r] & 0
        \end{tikzcd}
    \end{equation*}
    There, \(F,G\) are constructed as follows: since \(\pi({\mathbb{Z}}^n) = Q = \pi'({\mathbb{Z}}^{n'})\), for any \(e_j' \in {\mathbb{Z}}^{n'}\) there exists \(h_j = \sum_{i=1}^n h_j^i e_i\in {\mathbb{Z}}^n\) such that \(\pi'(e_j') = \pi(h_j)\). The assignment \(e_j' \mapsto h_j\) defines a linear map \(f : {\mathbb{R}}^{n'} \to {\mathbb{R}}^n\) which is rational since \(h_j^i \in {\mathbb{Z}}\) and satisfies \(\pi' = \pi \circ f\). This map induces \(F\) as the rational linear isomorphism represented by the matrix
    \begin{equation*}
        \begin{bmatrix}
            1_{{\mathbb{R}}^n} & f\\
            0 & 1_{{\mathbb{R}}^{n'}}
        \end{bmatrix};
    \end{equation*}
    moreover, it makes the diagram commute. Defining \(G\) symmetrically, we obtain a rational isomorphism \(\Phi = G \circ F^{-1}\) that restricts to a rational isomorphism
    \begin{equation*}
        \varphi : \operatorname{Rel}(V) \oplus {\mathbb{R}}^{n'} \longrightarrow {\mathbb{R}}^{n} \oplus \operatorname{Rel}(V')
    \end{equation*}
    by the universal property of kernels.

    Therefore, if \(W\) is the rational core of \(\operatorname{Rel}(V)\), by maximality, \(\widetilde W \coloneqq W \oplus {\mathbb{R}}^{n'}\) is the rational core of \(\operatorname{Rel}(V) \oplus {\mathbb{R}}^{n'}\). Since \(\varphi\) is rational, its image \(\varphi(\widetilde W)\) is the rational core of \( {\mathbb{R}}^{n} \oplus \operatorname{Rel}(V')\). This splits as \(\varphi(\widetilde W) = {\mathbb{R}}^n \oplus W'\), with \(W'\) the rational core of \(\operatorname{Rel}(V')\). A fortiori, this implies
    \begin{equation*}
        n - a(V) = n - \dim W = n + n' - \dim \widetilde W = n + n' - \dim \varphi(\widetilde W) = n' - \dim W' = n' - a(V').
    \end{equation*}

    By an entirely analogous argument applied to the rational envelopes of \(\operatorname{Rel}(V)\) and \(\operatorname{Rel}(V')\) respectively, we also deduce \(n - b(V) = n' - b(V')\).

For the first part we take \(S = {\mathbb{Z}}\setminus\{0\}\) as the maximal multiplicative system in \({\mathbb{Z}}\), so that
    \begin{equation*}
        \operatorname{Span}_{{\mathbb{Q}}}(v_1,\dots,v_n) = Q \otimes_{{\mathbb{Z}}} {\mathbb{Q}} \cong S^{-1}Q,
    \end{equation*}
    where the isomorphism is canonically induced by the bilinear map \((x,\frac{p}{q}) \mapsto \frac{px}{q}\) via the universal property of the tensor product. Since \(Q\) is a torsion-free, finitely generated module over a PID
    \begin{align*}
        \operatorname{rk} Q &= \operatorname{rk} S^{-1} Q\\
        &= \dim_{{\mathbb{Q}}} \operatorname{Span}_{\mathbb{Q}}(v_1,\dots,v_n)\\
        &= n - \dim_{{\mathbb{Q}}} (\operatorname{Rel}(V) \cap {\mathbb{Q}}^n)\\
        &= n - \dim_{{\mathbb{R}}} \operatorname{core}_{{\mathbb{Q}}}(\operatorname{Rel}(V))\\
        &= n-a(V).
    \end{align*}

    For the second part, we consider a new vector configuration \(V' = (w_1,\dots,w_{n'})\) which we assume to be adapted to the splitting \(Q = L \oplus Q_\text{d}\), i.e. such that \(\{w_1,\dots,w_r\}\) generates \(L\), and \(\{w_{r+1},\dots,w_{n'}\}\) generates \(Q_\text{d}\). We consider the linear map
    \begin{align*}
        \pi:{\mathbb{Z}}^{n'} &\longrightarrow Q\\
        e_i &\longmapsto w_i,
    \end{align*}
    and the subgroups
    \begin{equation*}
        D_1 = \operatorname{Span}_{{\mathbb{Z}}}(e_1,\dots,e_r) \subseteq {\mathbb{Z}}^{n'}, \quad D_2 = \operatorname{Span}_{{\mathbb{Z}}}(e_{r+1},\dots,e_{n'}) \subseteq {\mathbb{Z}}^{n'}.
    \end{equation*}
    With respect to the splitting \(D_1 \oplus D_2 = {\mathbb{Z}}^{n'}\), \(\pi\) decomposes as \(\pi_1 \oplus \pi_2\) according to the following diagram
    \begin{equation*}
        \begin{tikzcd}
            0 \ar[r] & K_1 \ar[r] \ar[d] & D_1 \ar[r,"\pi_1"] \ar[d] & L \ar[r] \ar[d] & 0\\
            0 \ar[r]& \ker\pi \ar[r]& {\mathbb{Z}}^{n'} \ar[r,"\pi"]& Q \ar[r]& 0\\
            0 \ar[r] & K_2 \ar[r] \ar[u]& D_2 \ar[r,"\pi_2"] \ar[u] & Q_{\text{d}} \ar[u] \ar[r]& 0
        \end{tikzcd}
    \end{equation*}
    where the vertical arrows are respectively the canonical coprojections and the canonical maps induced by them on kernels. Since \(L\) is a lattice in a complement of \(Q_\text{d} \otimes {\mathbb{R}} \subseteq {\mathbb{R}}^d\), we have \(\ker(\pi_1\otimes{\mathbb{R}}) = K_1 \otimes {\mathbb{R}}\). Moreover, with respect to the identifications above, 
    \begin{equation*}
        L \cong \frac{D_1}{K_1} \cong \frac{{\mathbb{Z}}^{n'}}{K_1 \oplus D_2}.
    \end{equation*}
    Let \(T = (K_1 \oplus D_2)\otimes {\mathbb{R}} \subseteq {\mathbb{R}}^{n'}\); this is a rational space containing \(\operatorname{Rel}(V')\). Indeed, \(K_1 \otimes {\mathbb{R}} = \ker(\pi_1\otimes{\mathbb{R}})\),
    \(D_2 \otimes {\mathbb{R}} \supseteq\ker(\pi_2\otimes{\mathbb{R}})\) and
    \begin{equation}
        \label{many_inclusions}
        (K_1 \oplus K_2) \otimes {\mathbb{R}} \subseteq \ker(\pi \otimes {\mathbb{R}}) = \ker(\pi_1 \otimes {\mathbb{R}}) \oplus \ker(\pi_2 \otimes {\mathbb{R}}) = \operatorname{Rel}(V').
    \end{equation}
    We claim that \(T\) is the rational envelope of \(\operatorname{Rel}(V')\). To verify this, consider any rational subspace \(T' \subseteq {\mathbb{R}}^{n'}\) containing \(\operatorname{Rel}(V')\); by \zcref{many_inclusions} it also contains \(K_1 \oplus K_2\). Such a \(T'\) must contain \(D_2 \otimes {\mathbb{R}}\) as well. Were this not the case, we could find a non-trivial linear functional \(f : D_2\otimes {\mathbb{R}} \to {\mathbb{R}}\) taking rational values on \(D_2\) and satisfying \(T' \cap D_2 \subseteq \ker f\); up to rescaling it, we may also assume \(f(D_2) \subseteq {\mathbb{Z}}\). Because of the inclusions
    \begin{equation*}
        \ker f \supseteq T' \cap (D_2 \otimes {\mathbb{R}}) \supseteq \operatorname{Rel}(V') \cap  (D_2 \otimes {\mathbb{R}}) \supseteq \ker(\pi_2\otimes{\mathbb{R}}),
    \end{equation*}
    \(f\) factors as 
    \begin{equation*}
        \begin{tikzcd}
            D_2 \otimes {\mathbb{R}} \ar[r, "f"] \ar[d, "p"'] & {\mathbb{R}}\\
            \frac{D_2\otimes {\mathbb{R}}}{\ker(\pi_2\otimes{\mathbb{R}})} \ar[ur, "\bar f"']
        \end{tikzcd}
    \end{equation*}
    and by construction \(\frac{D_2\otimes {\mathbb{R}}}{\ker(\pi_2\otimes{\mathbb{R}})} \cong Q_\text{d}\otimes {\mathbb{R}} \): this isomorphism identifies \(Q_\text{d}\) with a dense subgroup of the quotient. Evaluating \(\bar f\) on \(Q_\text{d}\), we have \(\bar f(Q_\text{d}) = (\bar f \circ p)(D_2) = f(D_2) \subseteq {\mathbb{Z}} \). On the other hand, since \(\bar f\) is continuous, \(\bar f(Q_\text{d})\) is dense in \(f(D_2 \otimes {\mathbb{R}})\): this forces \(f(D_2) = \{0\}\), a contradiction. Therefore, \(T' \supseteq T\), whence \(T\) is the rational envelope of \(\operatorname{Rel}(V')\). Thus, \(\dim_{{\mathbb{R}}} T = b(V')\) and \(\operatorname{rk}L = n' - b(V') = n - b(V)\), with the second equality following from \zcref[S]{rationality_measure_is_intrinsic}.

From the point of view of Loeb and Nicolau, \(N\) is the complex manifold generated by the action of the holomorphic flow of the vector field \(X_{x,y}\) on  \(\mathbb{P}(U(\mathcal{T}^*)) \cong ({\mathbb{C}}^2\setminus\{0\}) \times ({\mathbb{C}}^2\setminus\{0\})\)
    \begin{equation*}
        X_{x,y} = \sum_{j=2}^5 (\Lambda_{x,y})_{j-1} z_{j} \frac{\partial}{\partial z_{j}}.
    \end{equation*}
